import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`room-design`,heroTitle:`Redesign any room in minutes`,heroSubtitle:`Perplexity Computer analyzes your room photo, generates design concepts with furniture and decor picks, and builds a shoppable plan — automatically.`,hasInputUrl:!1,hasInputFile:!0,inputFileCta:`Upload your room photo`,inputFileAccept:`.pdf,.jpg,.jpeg,.png,.heic,.webp`,inputFilePrefill:`Analyze the uploaded room photo and perform a complete room redesign. 1) Identify the room type, current dimensions, layout, existing furniture, lighting conditions, and architectural features like windows, doors, and built-ins. 2) Generate 3 distinct design concepts — one modern/minimalist, one mid-century, and one transitional — each with a mood board, color palette, and material recommendations. 3) For each concept, recommend specific furniture pieces, lighting fixtures, rugs, artwork, and decor accessories with real product names, approximate dimensions, and estimated price ranges. 4) Provide a spatial layout plan showing furniture placement optimized for flow and function. 5) Include a prioritized shopping list organized by budget tiers (essentials, upgrades, splurges) with total estimated cost per concept. 6) Add quick-win styling tips the user can execute today with minimal spend.`,heroOverlaySteps:[`Analyzing your room's layout, lighting, and existing furniture`,`Generating three distinct design concepts with mood boards`,`Sourcing furniture, decor, and accessories with pricing`,`Design concepts, layouts, and shopping lists — ready to execute`],generatingSteps:[`Analyzing the uploaded file to identify room type, dimensions, and existing features`,`Designing an agent to generate multiple design concepts with color palettes and mood boards`,`Configuring product sourcing for furniture, lighting, and decor recommendations`,`Setting up your shoppable room plan with layouts and budget breakdowns`],featureSectionTitle:`From room photo to design plan`,featureCardTitles:[`Connects to your home stack`,`Outputs you can shop`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Sheets, Notion, Canva, Google Drive, Trello — Computer organizes your design plans, mood boards, and shopping lists in the tools you already use.`,`Mood boards with color palettes. Spatial layout plans. Furniture and decor picks with real pricing. A tiered shopping list you can start buying from today.`],capabilitySectionTitle:`Your interior designer, on autopilot`,capabilitySectionSubtitle:`Upload a photo, step away, come back to a complete room redesign.`,capabilityCards:[{title:`Room Analysis`,description:`Computer can analyze your photo — identifying room dimensions, natural light, architectural features, and existing furniture — to build a detailed design brief.`},{title:`Design Concepts`,description:`Computer can generate multiple design directions — each with a mood board, color palette, and material recommendations tailored to your space.`},{title:`Product Sourcing`,description:`Computer can find real furniture, lighting, rugs, and decor — with dimensions, price ranges, and style matches for each concept.`},{title:`Connect Your Tools`,description:`Computer can export to Google Sheets, Notion, Canva, and Google Drive — keep your mood boards, shopping lists, and layouts organized in one place.`},{title:`Remember Your Style`,description:`Computer can remember your design preferences, past room projects, and favorite brands — so every new room feels cohesive with your home.`},{title:`Price Drop Alerts`,description:`Computer can monitor your shopping list for sales and restocks — and notify you when recommended pieces drop in price.`}]});export{t as default};
